.sockets{display:flex;justify-content:space-between;align-items:center;padding:15px 0 8px;gap:12px;font-family:"Courier New",monospace;font-size:12px}.sockets span:first-child{color:var(--water)}.outlet{padding:10px 0 0;text-align:right;color:var(--water);font-family:"Courier New",monospace;font-size:12px}
