.tile:hover{background:#306050}.tile svg{display:block;width:100%;height:100%;overflow:hidden}.tile .outer{stroke:#0d2924;stroke-width:29;fill:none;stroke-linecap:butt}.tile .metal{stroke:#d7a76b;stroke-width:22;fill:none}.tile .shine{stroke:#edcfa0;stroke-width:3;fill:none;opacity:.7}.tile .fluid{stroke:var(--water);stroke-width:11;fill:none;opacity:0}.tile.wet .fluid{opacity:1}.tile.wet{background:#285d52}.tile.leak{border:2px solid #ff9579;background:#763c2c}.tile.hinted{box-shadow:inset 0 0 0 3px #f8e3a2}.tile .rivets{fill:#719083}.tile .number{font:10px "Courier New",monospace;fill:#d6e1c080}.tile.solved{cursor:default}.controls{display:flex;gap:10px;margin-top:18px}.flush{background:var(--brass);color:#173d35;border:0;border-bottom:4px solid #91652c;border-radius:4px;padding:13px 20px;font-weight:bold;font-size:18px;flex:1}.secondary{background:transparent;border:1px solid #d8a65c88;color:var(--cream);border-radius:4px;padding:10px 14px}.secondary:hover{background:#ffffff0d}.feedback{min-height:65px;font-size:16px;margin:16px 0 0;line-height:1.5}.feedback.success{color:#abedcb}.feedback.error{color:#ffc6ae}
.side{padding:7px 0}.side h2{font-size:28px;font-weight:normal;margin:10px 0 18px}.levels{display:grid;gap:8px}.level{display:grid;grid-template-columns:30px 1fr auto;gap:8px;align-items:center;text-align:left;border:1px solid #153d3640;background:#fff8e960;padding:12px 10px;min-height:48px;color:var(--ink)}.level[aria-current=true]{background:var(--ink);color:var(--cream)}.level b{font-family:"Courier New",monospace;font-size:12px;font-weight:normal}.level .check{font-size:17px}
