.next{width:100%;margin-top:14px;background:var(--ink);color:var(--cream);border:0;padding:14px}.next[hidden]{display:none}.how{display:grid;grid-template-columns:1fr 1fr 1fr;gap:25px;border-top:1px solid #153d3640;margin-top:40px;padding-top:24px}.how h3{font-size:20px;font-weight:normal;margin:8px 0}.how p{font-size:14px;margin-top:0}.how .n{color:#a85a2e;font-family:"Courier New",monospace;font-size:12px}.footer{font-size:13px;border-top:1px solid #153d3640;margin-top:20px;padding-top:20px;line-height:1.7}.footer p{margin:5px 0}.reset{background:none;color:inherit;border:0;text-decoration:underline;text-underline-offset:3px;padding:5px 0;font-size:13px}noscript{display:block;background:#ffe7bf;padding:20px;margin-bottom:20px}
