<body><div class="wrap">
<nav><a href="index.php">← Chloe reads Jon</a><span>Department of small wonders / No. 26</span></nav>
<header class="hero"><div><div class="eyebrow">A delightfully low-stakes engineering game</div><h1>The Great<br><em><span>Flush</span> Works.</em></h1><p class="intro">Five pipe puzzles. One very important destination. Get the water from the tank to the throne.</p><p class="byline">No timer. No mess. Absolutely no call-out fee.</p></div>
<figure class="plate"><img src="data:image/webp;base64," width="1100" height="733" alt="Cutaway illustration: a raised cistern feeds blue water through brass pipework into a porcelain toilet, showing the tank-to-bowl journey." fetchpriority="high"><figcaption>PLATE I · TANK → PIPEWORK → PORCELAIN GLORY</figcaption></figure></header>
<noscript>Turn on JavaScript to rotate the pipes and run the waterworks.</noscript>
<main class="workshop">
<section class="machine" aria-label="Pipe puzzle">
<div class="machinehead"><h2 id="levelTitle">The first flush</h2><span class="serial" id="serial">WORK ORDER 01 / 05</span></div>
<div class="sockets"><span>↓ TANK INLET · TOP LEFT</span><span id="sizeLabel">4 × 4</span></div>
<div id="board" class="board" role="group" aria-label="Rotatable pipe fittings"></div>
<div class="outlet">BOWL OUTLET · BOTTOM RIGHT ↓</div>
<div class="controls"><button class="flush" id="flush">Pull the flush ↓</button><button class="secondary" id="hint">Fix one pipe</button><button class="secondary" id="reset">Reset</button></div>
<p id="feedback" class="feedback" role="status" aria-live="polite">Tap a fitting to rotate it clockwise. Join the two blue sockets, then pull the flush.</p>
</section>
<aside class="side"><div class="label">The apprentice’s ledger</div><h2>A small career in plumbing.</h2><div id="levels" class="levels" aria-label="Choose a puzzle"></div>
<div class="stats"><div><strong id="moves">0</strong><span>Turns</span></div><div><strong id="completed">0 / 5</strong><span>Approved</span></div><div><strong id="hints">0</strong><span>Repairs</span></div></div>
<div class="note"><div class="label">Behind the porcelain</div><h3 id="factTitle">Stored potential</h3><p id="fact"></p></div>
<button id="next" class="next" hidden>Next work order →</button><button id="restart" class="reset">Start the whole apprenticeship again</button>
</aside>
</main>
<section class="how" aria-label="How to play"><div><span class="n">01 / TURN</span><h3>Make the connections.</h3><p>Tap or click any square. Each turn rotates its two openings 90°. Keyboard: Tab to a fitting, then Enter or Space.</p></div><div><span class="n">02 / TEST</span><h3>Follow the blue.</h3><p>Pull the flush to trace the water. A red fitting marks the first bad connection. Spare pipes do not all need to be used.</p></div><div><span class="n">03 / TINKER</span><h3>Take your time.</h3><p>Every order is solvable. “Fix one pipe” repairs the first wrong fitting on a known route. Reset restores the original arrangement.</p></div></section>
<footer class="footer"><p>Inspired by Jon’s <a href="?source=1">Choosing a toilet</a>, a 2010 post that finds genuine wonder in a good flush.</p><p>A connection puzzle, not a fluid-dynamics simulation: real toilets use much more elegant internal passages. The water here is imaginary, and your progress stays on this page.</p><p>Original illustrated workshop plate made with GPT Image. <a href="index.php">More small wonders →</a></p></footer>
</div>
<script>
'use strict';
const orders=[
{n:4,title:'The first flush',route:[0,1,5,6,10,14,15],factTitle:'Stored potential',fact:'In a gravity-fed toilet, the tank holds water above the bowl. Opening the flush valve releases that stored water; gravity supplies the energy.'},
{n:4,title:'The scenic route',route:[0,4,8,9,5,6,2,3,7,11,10,14,15],factTitle:'A seal made of water',fact:'The curved trapway retains water after a flush. That water seal helps stop sewer gases coming back into the room. Our square pipes are just a puzzle version of the idea.'},
{n:5,title:'The copper detour',route:[0,1,2,7,6,11,16,17,12,13,8,9,14,19,18,23,24],factTitle:'The siphon moment',fact:'In a siphonic toilet, water filling the trapway can start a siphon that helps empty the bowl. Air entering at the end breaks the siphon. Not every toilet uses the same flushing design.'},
{n:5,title:'Under the floorboards',route:[0,5,10,11,6,7,2,3,4,9,14,13,18,17,22,23,24],factTitle:'The quiet refill',fact:'After a flush, the fill valve replenishes the tank and a refill tube helps restore the water in the bowl. The float tells the fill valve when the tank has enough water.'},
{n:6,title:'The porcelain finale',route:[0,1,7,6,12,18,19,13,14,8,2,3,4,10,16,15,21,27,26,32,33,34,28,22,23,29,35],factTitle:'The tiniest leak',fact:'A worn flapper or flush-valve seal can let tank water seep into the bowl between flushes. A toilet can waste water quietly, even when nobody touches the handle.'}
];
const board=document.querySelector('#board'), feedback=document.querySelector('#feedback');
const offsets=[[-1,0],[0,1],[1,0],[0,-1]],directionNames=['north','east','south','west'];
let current=0,tiles=[],turns=0,repairs=0,running=false,solved=false,runToken=0;
const approved=new Set();
function direction(a,b,n){const ar=Math.floor(a/n),ac=a%n,br=Math.floor(b/n),bc=b%n;return offsets.findIndex(([r,c])=>ar+r===br&&ac+c===bc)}
function equal(a,b){return a.length===b.length&&a.every(x=>b.includes(x))}
function solution(order){
 const wanted=new Map();order.route.forEach((i,k)=>wanted.set(i,[k===0?0:direction(i,order.route[k-1],order.n),k===order.route.length-1?2:direction(i,order.route[k+1],order.n)]));return wanted;
}
function initial(order){
 const wanted=solution(order);
 return Array.from({length:order.n*order.n},(_,i)=>{
 const target=wanted.get(i)||((i%3===0)?[0,2]:[0,1]);
 // Deterministic scramble: each work order is identical on every visit.
 const rotation=1+(i*7+current)%3;
 return target.map(x=>(x+rotation)%4);
 });
}
function pipePath(ports){
 const end=[[50,0],[100,50],[50,100],[0,50]],a=end[ports[0]],b=end[ports[1]];
 return Math.abs(ports[0]-ports[1])===2?'M '+a.join(' ')+' L '+b.join(' '):'M '+a.join(' ')+' Q 50 50 '+b.join(' ');
}
function draw(){
 board.style.gridTemplateColumns='repeat('+orders[current].n+',minmax(0,1fr))';
 board.innerHTML=tiles.map((ports,i)=>{const d=pipePath(ports),row=Math.floor(i/orders[current].n)+1,col=i%orders[current].n+1;
 return '<button class="tile'+(solved?' solved':'')+'" data-i="'+i+'" aria-label="Row '+row+', column '+col+': '+ports.map(p=>directionNames[p]).join(' and ')+'. Rotate clockwise."'+(running||solved?' disabled':'')+'><svg viewBox="0 0 100 100" aria-hidden="true"><circle class="rivets" cx="8" cy="8" r="2"/><circle class="rivets" cx="92" cy="92" r="2"/><path class="outer" d="'+d+'"/><path class="metal" d="'+d+'"/><path class="shine" d="'+d+'"/><path class="fluid" d="'+d+'"/><text class="number" x="7" y="94">'+String(i+1).padStart(2,'0')+'</text></svg></button>';
 }).join('');
 document.querySelector('#moves').textContent=turns;document.querySelector('#hints').textContent=repairs;
 document.querySelector('#completed').textContent=approved.size+' / 5';
 document.querySelector('#flush').disabled=running||solved;document.querySelector('#hint').disabled=running||solved;
 document.querySelector('#next').hidden=!solved;
 document.querySelector('#next').textContent=current===4?'Return to the first order ↺':'Next work order →';
 document.querySelectorAll('.level').forEach((b,i)=>{b.setAttribute('aria-current',i===current?'true':'false');b.querySelector('.check').textContent=approved.has(i)?'✓':''});
}
function message(text,kind=''){feedback.textContent=text;feedback.className='feedback '+kind}
function load(i){
 runToken++;running=false;solved=false;current=i;turns=0;repairs=0;
 tiles=initial(orders[i]);document.querySelector('#levelTitle').textContent=orders[i].title;
 document.querySelector('#serial').textContent='WORK ORDER '+String(i+1).padStart(2,'0')+' / 05';
 document.querySelector('#sizeLabel').textContent=orders[i].n+' × '+orders[i].n;
 document.querySelector('#factTitle').textContent=orders[i].factTitle;document.querySelector('#fact').textContent=orders[i].fact;
 message('Tap a fitting to rotate it clockwise. Join the two blue sockets, then pull the flush.');draw();
}
function trace(){
 const n=orders[current].n,seen=new Set(),path=[];
 let i=0,entry=0;
 for(let step=0;step<n*n+1;step++){
  if(seen.has(i))return {path,bad:i,reason:'The water has gone in a circle. An ambitious fountain, but not a flush.'};
  seen.add(i);
  if(!tiles[i].includes(entry))return {path,bad:i,reason:'The water meets a closed side at fitting '+(i+1)+'. Turn that fitting to meet the incoming pipe.'};
  path.push(i);const exit=tiles[i].find(x=>x!==entry);
  if(i===n*n-1&&exit===2)return {path,win:true};
  const r=Math.floor(i/n)+offsets[exit][0],c=i%n+offsets[exit][1];
  if(r<0||r>=n||c<0||c>=n)return {path,bad:i,reason:'Fitting '+(i+1)+' sends the water out of the cabinet. The bowl outlet is below the bottom-right square.'};
  i=r*n+c;entry=(exit+2)%4;
 }
 return {path,bad:i,reason:'Something is going round in circles. Try a different connection.'};
}
board.addEventListener('click',e=>{
 const button=e.target.closest('button');if(!button||running||solved)return;
 const i=Number(button.dataset.i);tiles[i]=tiles[i].map(p=>(p+1)%4);turns++;
 message('Fitting '+(i+1)+' turned. Ready when you are.');draw();board.querySelector('[data-i="'+i+'"]').focus({preventScroll:true});
});
document.querySelector('#flush').addEventListener('click',async()=>{
 if(running||solved)return;running=true;const token=++runToken,result=trace();draw();message('Water away… following the blue.');
 const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 for(const i of result.path){
  if(token!==runToken)return;
  board.children[i].classList.add('wet');
  await new Promise(resolve=>setTimeout(resolve,reduce?0:90));
 }
 if(token!==runToken)return;running=false;
 if(result.win){solved=true;approved.add(current);draw();result.path.forEach(i=>board.children[i].classList.add('wet'));
 message(approved.size===5?'All five approved! You are now Chief Officer of Porcelain Affairs. A distinguished appointment.':'A magnificent flush. Work order approved! '+turns+' turns, '+repairs+' assisted repairs.','success');
 }else{draw();result.path.forEach(i=>board.children[i].classList.add('wet'));board.children[result.bad].classList.add('leak');message(result.reason,'error')}
});
document.querySelector('#hint').addEventListener('click',()=>{
 if(running||solved)return;const wanted=solution(orders[current]);
 const found=orders[current].route.find(i=>!equal(tiles[i],wanted.get(i)));
 if(found===undefined){message('Every fitting on the known route is ready. Pull the flush!');return}
 tiles[found]=[...wanted.get(found)];repairs++;draw();board.children[found].classList.add('hinted');
 message('Repaired fitting '+(found+1)+' on one known route. You can still find a different route of your own.');
});
document.querySelector('#reset').addEventListener('click',()=>load(current));
document.querySelector('#next').addEventListener('click',()=>{load((current+1)%orders.length);document.querySelector('#levelTitle').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})});
document.querySelector('#restart').addEventListener('click',()=>{approved.clear();load(0)});
document.querySelector('#levels').innerHTML=orders.map((o,i)=>'<button class="level" data-level="'+i+'"><b>0'+(i+1)+'</b><span>'+o.title+'</span><span class="check" aria-label="Approved"></span></button>').join('');
document.querySelector('#levels').addEventListener('click',e=>{const b=e.target.closest('button');if(b)load(Number(b.dataset.level))});
load(0);
</script>
</body></html>